def solve_demo():
    height = len(demo_in)
    width = len(demo_in[0]) if demo_in else 0

    # Create copy of input
    result = [list(row) for row in demo_in]

    uniform_rows = []
    uniform_cols = []
    special_color = None

    for i, row in enumerate(result):
        if len(set(row)) == 1:
            uniform_rows.append(i)
            special_color = row[0]

    for j in range(width):
        col = [result[i][j] for i in range(height)]
        if len(set(col)) == 1:
            uniform_cols.append(j)
            if special_color is None:
                special_color = col[0]

    # Fill uniform rows and cols with 2
    for i in uniform_rows:
        for j in range(width):
            result[i][j] = 2
    for j in uniform_cols:
        for i in range(height):
            result[i][j] = 2

    return result

